{
  "headline": "FDA's records trace our supply to a plant classified OAI 275 days before the posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "FDA first posted the rifampin injection shortage on 2021-02-17 and it remains Current as of 2026-10-21.",
      "cites": ["E21"]
    },
    {
      "text": "The shortage entry names Fresenius Kabi USA, LLC (NDC 63323-351-20) as the company.",
      "cites": ["E17"]
    },
    {
      "text": "A registered plant for that labeler, Fresenius Kabi USA LLC (FEI 1450022), received an OAI classification after an inspection that ended 2020-05-18, with the classification letter dated 2024-05-22.",
      "cites": ["E11", "E14"]
    },
    {
      "text": "That inspection ended 275 days before FDA posted the shortage on 2021-02-17.",
      "cites": ["D6"]
    },
    {
      "text": "A second inspection of the same plant ended 2022-06-30 and was also classified OAI, with the letter dated 2024-04-30.",
      "cites": ["E12"]
    },
    {
      "text": "Our Corvale sites use Mylan Institutional LLC product (NDC 67457-445-60) which is interchangeable with the Fresenius Kabi product per P&T approval.",
      "cites": ["E2", "E4", "E5", "E22"]
    },
    {
      "text": "The top-ranked mitigation is to transfer 17 vials of 600 mg/10 mL from Corvale Lakeside to Corvale East, which would raise East's supply from 4.4 days to 10 days while Lakeside retains two weeks on hand.",
      "cites": ["D1", "D3", "D11"]
    }
  ]
}
